import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
import {projectFinalAuditCorrections as project} from '../../../scripts/final-audit-corrections.mjs';
import {projectReferenceMetadata} from '../../../scripts/metadata-card-corrections.mjs';
import {projectLateWikiMetadata} from '../../../scripts/late-wiki-corrections.mjs';
import {projectVoiceMetadata} from '../../../scripts/voice-factual-correction.mjs';
import {projectAuditMetadata,projectReviewedComparisonMetadata} from '../../../scripts/audit-metadata-correction.mjs';
import {validateFinalAuditMetadata as validate} from '../../../scripts/final-audit-metadata.mjs';
import {eighthProof,assertEighthAll} from '../eighth-reconciliation/verify-dependencies.mjs';
const root=new URL('../../../',import.meta.url),raw=p=>fs.readFileSync(new URL(p,root)),read=p=>JSON.parse(raw(p)),sha=s=>createHash('sha256').update(s).digest('hex');
const bytes=fs.readFileSync(new URL('./transition-proof.json',import.meta.url));assert.equal(sha(bytes),'17c31f5fca97c737c7d4222da3093952a2f9c31e6d58769d16b2c6bc9db7349e');export const metadataBuildfixProof=JSON.parse(bytes);
const p=metadataBuildfixProof;assert.equal(sha(p.beforeBytes),p.beforeSha256);assert.equal(sha(p.afterBytes),p.afterSha256);assert.deepEqual(JSON.parse(p.beforeBytes),p.beforeRegistry);assert.deepEqual(JSON.parse(p.afterBytes),p.afterRegistry);assert.equal(p.beforeRegistry.records.length,30);assert.equal(p.afterRegistry.records.length,31);assert.deepEqual(p.afterRegistry,{...p.beforeRegistry,records:[...p.beforeRegistry.records,p.addedReview]});assert.equal(p.addedReview.key,'bg-线上排障-2#4');
// This historical view requires the complete current registry, not a permissive prefix.
export function metadataReviewBefore(actual){assert.deepEqual(actual,p.afterRegistry,'complete reviewed31 metadata objects required');return structuredClone(p.beforeRegistry);}
export function metadataBytesBefore(actual){assert.equal(String(actual),p.afterBytes,'complete reviewed31 metadata bytes required');return p.beforeBytes;}
export function assertBuildfixSources(){const b=fs.readFileSync(new URL('./source-transitions.json',import.meta.url));assert.equal(sha(b),'0864fc90eababd20aa48b063152e2d957cf2048bf688ea73aae55391185016a8');const proof=JSON.parse(b);for(const r of proof.files){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);let out=r.before;for(const e of r.replacements){assert.equal(out.split(e.before).length,2);out=out.replace(e.before,e.after);}assert.equal(out,r.after);assert.equal(raw(r.target).toString(),r.after);}return proof.files.length;}
export function actualMetadataContext(){const entries=[];for(const f of fs.readdirSync(new URL('dist/data/chapters/',root)).filter(f=>f.endsWith('.json')).sort())entries.push(...read('dist/data/chapters/'+f).entries);const E=new Map(entries.map(e=>[e.id,e]));assert.equal(E.size,entries.length);assertEighthAll(E);const registry=read('content/final-audit-corrections.json');assert.equal(registry.records.length,500);const before=project(entries,registry,{reverse:true});assert.deepEqual(project(before,registry),entries,'historical input reconstructed only after exact current500 guards');
 for(const[f,h]of Object.entries(p.inputHashes))assert.equal(sha(raw(f)),h,'same production input/code '+f);
 const metadata=projectReviewedComparisonMetadata(projectAuditMetadata(projectVoiceMetadata(projectLateWikiMetadata(projectReferenceMetadata(read('content/metadata.json'),read('content/metadata-card-corrections.json')),read('content/late-wiki-metadata-corrections.json')),read('content/voice-factual-correction.json'))),before,read('content/comparison-card-factual-corrections.json'));
 assert.deepEqual(metadata,p.reviewedMetadataBeforeFinal,'entire production metadata input');const reviews=read('content/final-audit-comparison-review.json');assert.deepEqual(reviews,p.afterRegistry);const output=validate(metadata,before,entries,reviews);assert.deepEqual(output,p.finalMetadata,'entire production metadata output');assert.deepEqual(read('dist/data/catalog.json').HL,output.HL,'actual built catalog matches full production HL');
 const oldMap=new Map(before.map(e=>[e.id,e])),required=[];for(const[k,card]of Object.entries(metadata.HL.cards)){const m=/^(.+)#(0|[1-9]\d*)$/.exec(k);if(!m)continue;const a=oldMap.get(m[1])?.items?.[+m[2]],b=E.get(m[1])?.items?.[+m[2]];if(a&&b&&(a.q!==b.q||a.a!==b.a||a.lead!==b.lead))required.push(k);}assert.deepEqual(required.sort(),p.allRequiredPairKeys);assert.deepEqual(required,reviews.records.map(r=>r.key).sort());assert.equal(required.length,31);assert.equal(Object.keys(metadata.HL.cards).length,122);
 const keys=[...new Set(eighthProof.records.filter(r=>r.path[0]==='items').map(r=>r.entryId+'#'+r.path[1]))].sort();assert.deepEqual(keys,p.candidateItemKeys);assert.deepEqual(keys.filter(k=>Object.hasOwn(metadata.HL.cards,k)),p.reviewedCandidateCards.map(c=>c.key));for(const c of p.reviewedCandidateCards){const[id,i]=c.key.split('#');assert.deepEqual(E.get(id).items[+i],c.finalQuestion);assert.deepEqual(output.HL.cards[c.key],c.finalCard);assert.deepEqual(reviews.records.find(r=>r.key===c.key),c.finalReview);assert.ok(c.semanticReview.length>50);}
 return{entries,before,metadata,reviews,required};}
export function assertAllPairFailures(c){let missing=0,cards=0,answers=0;for(const key of c.required){const without={...c.reviews,records:c.reviews.records.filter(r=>r.key!==key)};assert.throws(()=>validate(c.metadata,c.before,c.entries,without),e=>e.message==='Final metadata: unreviewed answer/card pair '+key);missing++;const changed=structuredClone(c.metadata);changed.HL.cards[key].rows[0].cells[0]+=' drift';assert.throws(()=>validate(changed,c.before,c.entries,c.reviews),/Final metadata: (input card|paired review) drift/);cards++;const[id,i]=key.split('#'),entries=c.entries.map(e=>e.id===id?structuredClone(e):e);entries.find(e=>e.id===id).items[+i].a+=' drift';assert.throws(()=>validate(c.metadata,c.before,entries,c.reviews),/Final metadata: paired review drift/);answers++;}assert.throws(()=>validate(c.metadata,c.before,c.entries,p.beforeRegistry),/unreviewed answer\/card pair bg-线上排障-2#4/);return{missing,cards,answers};}
